create extension if not exists "pgcrypto";

create type public.user_role as enum ('EMPRENDEDOR', 'ADMINISTRADOR', 'SUPER_ADMIN');
create type public.rule_status as enum ('BORRADOR', 'EN_REVISION', 'VERIFICADA', 'PUBLICADA', 'DESACTUALIZADA');
create type public.requirement_status as enum ('PENDIENTE', 'EN_PROCESO', 'COMPLETADO', 'NO_APLICA', 'REQUIERE_REVISION');

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null default '', role public.user_role not null default 'EMPRENDEDOR',
  phone text, department text, province text, district text, created_at timestamptz not null default now()
);
create table public.businesses (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id),
  name text not null, purpose text not null check (purpose in ('crear','formalizar','revisar')),
  department text not null, province text not null, district text not null, status text not null default 'EN_PROCESO', created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.business_members (business_id uuid references public.businesses(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role text not null default 'OWNER', primary key (business_id, user_id));
create table public.business_activities (id uuid primary key default gen_random_uuid(), name text not null, category text not null, active boolean not null default true, unique(name));
create table public.ciiu_codes (id uuid primary key default gen_random_uuid(), code text not null unique, description text not null, revision text not null default 'CIIU Rev. 4', active boolean not null default true, updated_at timestamptz not null default now());
create table public.activity_ciiu (activity_id uuid references public.business_activities(id) on delete cascade, ciiu_id uuid references public.ciiu_codes(id) on delete cascade, primary key(activity_id, ciiu_id));
create table public.questions (id uuid primary key default gen_random_uuid(), code text not null unique, label text not null, help_text text, field_type text not null, position int not null, active boolean not null default true);
create table public.question_options (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, value text not null, label text not null, position int not null);
create table public.question_dependencies (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, depends_on_question_id uuid not null references public.questions(id) on delete cascade, operator text not null, expected_value jsonb not null);
create table public.business_answers (business_id uuid not null references public.businesses(id) on delete cascade, question_id uuid not null references public.questions(id), value jsonb not null, updated_at timestamptz not null default now(), primary key(business_id, question_id));
create table public.institutions (id uuid primary key default gen_random_uuid(), name text not null unique, acronym text, website text, active boolean not null default true);
create table public.sources (id uuid primary key default gen_random_uuid(), slug text not null unique, institution_id uuid references public.institutions(id), title text not null, url text not null, status text not null default 'VIGENTE', reviewed_at date not null, notes text);
create table public.requirements (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, category text not null, description text not null, institution_id uuid references public.institutions(id), documents jsonb not null default '[]', active boolean not null default true);
create table public.requirement_sources (requirement_id uuid references public.requirements(id) on delete cascade, source_id uuid references public.sources(id) on delete restrict, primary key(requirement_id, source_id));
create table public.rules (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.rule_versions (id uuid primary key default gen_random_uuid(), rule_id uuid not null references public.rules(id) on delete cascade, version int not null, status public.rule_status not null default 'BORRADOR', source_id uuid not null references public.sources(id), effective_from date not null, effective_to date, priority int not null default 0, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), unique(rule_id, version));
create table public.rule_conditions (id uuid primary key default gen_random_uuid(), rule_version_id uuid not null references public.rule_versions(id) on delete cascade, group_path text not null default 'root', connector text not null default 'AND', field text not null, operator text not null, expected_value jsonb, position int not null default 0);
create table public.rule_actions (id uuid primary key default gen_random_uuid(), rule_version_id uuid not null references public.rule_versions(id) on delete cascade, requirement_id uuid not null references public.requirements(id), classification text not null, reason_template text not null, position int not null default 0);
create table public.business_diagnostics (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, context_snapshot jsonb not null, rules_version_snapshot jsonb not null, created_at timestamptz not null default now());
create table public.diagnostic_rules (diagnostic_id uuid references public.business_diagnostics(id) on delete cascade, rule_version_id uuid references public.rule_versions(id), primary key(diagnostic_id, rule_version_id));
create table public.diagnostic_results (id uuid primary key default gen_random_uuid(), diagnostic_id uuid not null references public.business_diagnostics(id) on delete cascade, requirement_id uuid not null references public.requirements(id), rule_version_id uuid references public.rule_versions(id), classification text not null, reason text not null, source_id uuid references public.sources(id));
create table public.business_requirements (business_id uuid references public.businesses(id) on delete cascade, requirement_id uuid references public.requirements(id), diagnostic_result_id uuid references public.diagnostic_results(id) on delete cascade, status public.requirement_status not null default 'PENDIENTE', updated_at timestamptz not null default now(), primary key(business_id, requirement_id));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, old_value jsonb, new_value jsonb, created_at timestamptz not null default now());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name) values (new.id, coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select coalesce((select role in ('ADMINISTRADOR','SUPER_ADMIN') from public.profiles where id = auth.uid()), false); $$;

alter table public.profiles enable row level security; alter table public.businesses enable row level security; alter table public.business_members enable row level security; alter table public.business_answers enable row level security; alter table public.business_diagnostics enable row level security; alter table public.diagnostic_results enable row level security; alter table public.business_requirements enable row level security;
create policy "profile owner" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "business owner" on public.businesses for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "member sees own business" on public.business_members for select using (user_id = auth.uid());
create policy "owner manages answers" on public.business_answers for all using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid())) with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));
create policy "owner sees diagnostics" on public.business_diagnostics for select using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));
create policy "owner sees results" on public.diagnostic_results for select using (exists (select 1 from public.business_diagnostics d join public.businesses b on b.id = d.business_id where d.id = diagnostic_id and b.owner_id = auth.uid()));
create policy "owner manages progress" on public.business_requirements for all using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid())) with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));

alter table public.business_activities enable row level security; alter table public.ciiu_codes enable row level security; alter table public.activity_ciiu enable row level security; alter table public.questions enable row level security; alter table public.question_options enable row level security; alter table public.question_dependencies enable row level security; alter table public.institutions enable row level security; alter table public.sources enable row level security; alter table public.requirements enable row level security; alter table public.requirement_sources enable row level security; alter table public.rules enable row level security; alter table public.rule_versions enable row level security; alter table public.rule_conditions enable row level security; alter table public.rule_actions enable row level security; alter table public.audit_logs enable row level security;
create policy "catalog is readable" on public.business_activities for select using (true); create policy "ciiu is readable" on public.ciiu_codes for select using (true); create policy "activities ciiu readable" on public.activity_ciiu for select using (true); create policy "questions readable" on public.questions for select using (true); create policy "options readable" on public.question_options for select using (true); create policy "dependencies readable" on public.question_dependencies for select using (true); create policy "institutions readable" on public.institutions for select using (true); create policy "sources readable" on public.sources for select using (true); create policy "requirements readable" on public.requirements for select using (true); create policy "requirement sources readable" on public.requirement_sources for select using (true); create policy "rules readable" on public.rules for select using (true); create policy "published versions readable" on public.rule_versions for select using (status = 'PUBLICADA'); create policy "conditions readable" on public.rule_conditions for select using (true); create policy "actions readable" on public.rule_actions for select using (true); create policy "admins see audit" on public.audit_logs for select using (public.is_admin());
create policy "admins manage activities" on public.business_activities for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage questions" on public.questions for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage requirements" on public.requirements for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage rules" on public.rules for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage versions" on public.rule_versions for all using (public.is_admin()) with check (public.is_admin());
